// probe.test.js — sonde personnelle du playtesteur (D1–D7), retirée à la livraison.
// Les cas du symptôme « la balle traverse les briques » sont déjà dans game/sonde.test.js ;
// ce fichier ajoute les deux familles que la sonde ne couvre pas (paddle, vitesse) et des
// vérifications directes via step() pour piloter l'implémentation en TDD.

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { step, createState, ballSpeed, BALL_R, BRICK_W, BRICK_H } from '../game/neon.js';

const DT = 1 / 60;
const DT_MAX = 0.05;
const EPS = 1e-9;

function brique(x = 100, y = 100, row = 0) {
  return { x, y, w: BRICK_W, h: BRICK_H, row, alive: true, points: 10 };
}

// D1 : un recouvrement doit produire un rebond sur l'axe de la face touchée.
test('D1 step: flanc gauche -> vx s_inverse, vy inchangé', () => {
  const state = createState(1);
  state.bricks = [brique()];
  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };

  step(state, DT);

  assert.ok(state.ball.vx < 0, `vx devait devenir négatif : ${state.ball.vx}`);
