// --- Brick collision helpers ------------------------------------------------

// Pushes the ball out of a brick it overlaps, along the axis of least
// penetration, and flips that component. On a corner (equal penetration on
// both axes) both components are flipped. The push is computed from the
// position the ball occupied BEFORE this frame's move: that is the face it
// came through.
function resolveOverlap(ball, prevX, prevY, brick) {
  const penX = Math.min(prevX + ball.r - brick.x, brick.x + brick.w - (prevX - ball.r));
  const penY = Math.min(prevY + ball.r - brick.y, brick.y + brick.h - (prevY - ball.r));
  if (penX <= penY) {
    ball.x = prevX <= brick.x ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.vx = -ball.vx;
  }
  if (penY <= penX) {
    ball.y = prevY <= brick.y ? brick.y - ball.r : brick.y + brick.h + ball.r;
    ball.vy = -ball.vy;
  }
}

// Swept test: the first contact of the segment (x0,y0)->(x1,y1) with the
// brick inflated by the ball radius (Minkowski sum). The ball is treated as a
// point against that inflated rect, so the returned time `t` is the fraction
// of the move at which the ball touches the real brick face. `axis` is the
// face entered last — the one to flip. Returns null when there is no contact
// this move. Discrete overlap at the start position must be resolved first
// (see step): the swept test assumes the ball starts outside.
function sweptHit(x0, y0, x1, y1, brick, r) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  let tmin = 0;
  let tmax = 1;
  let entryX = null;
  let entryY = null;

  if (Math.abs(dx) < 1e-12) {
    if (x0 < brick.x - r || x0 > brick.x + brick.w + r) return null;
  } else {
    entryX = Math.min((brick.x - r - x0) / dx, (brick.x + brick.w + r - x0) / dx);
    tmin = Math.max(tmin, entryX);
    tmax = Math.min(tmax, Math.max((brick.x - r - x0) / dx, (brick.x + brick.w + r - x0) / dx));
  }
  if (Math.abs(dy) < 1e-12) {
    if (y0 < brick.y - r || y0 > brick.y + brick.h + r) return null;
  } else {
    entryY = Math.min((brick.y - r - y0) / dy, (brick.y + brick.h + r - y0) / dy);
    tmin = Math.max(tmin, entryY);
    tmax = Math.min(tmax, Math.max((brick.y - r - y0) / dy, (brick.y + brick.h + r - y0) / dy));
  }
  if (tmin > tmax || tmin > 1) return null;
  const axis = entryY === null || (entryX !== null && entryX >= entryY) ? 'x' : 'y';
  return { t: tmin, axis };
}

// One brick broken, counted once, combo incremented.
function killBrick(state, brick) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks, first pass: a ball already overlapping a brick at the start of the
  // frame is pushed out through the face it came from. One bounce per pass —
  // the first overlapping brick wins, so a grid seam (gap 8 px < ball diameter
  // 14 px) can never flip the same axis twice and cancel out.
  let bounced = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides({ x: prevX, y: prevY, r: ball.r }, brick)) {
      resolveOverlap(ball, prevX, prevY, brick);
      killBrick(state, brick);
      bounced = true;
      break;
    }
  }

  // Bricks, second pass: swept detection between the two sampled positions.
  // A fast ball (level >= 6 on a 50 ms frame moves 35.5 px, more than the
  // 34 px it takes to jump a brick) never overlaps a brick at either endpoint,
  // so only the segment crossing reveals the hit. The earliest contact wins.
  if (!bounced) {
    let first = null;
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const hit = sweptHit(prevX, prevY, ball.x, ball.y, brick, ball.r);
      if (hit && (first === null || hit.t < first.hit.t)) {
        first = { brick, hit };
      }
    }
    if (first) {
      const { brick, hit } = first;
      ball.x = prevX + (ball.x - prevX) * hit.t;
      ball.y = prevY + (ball.y - prevY) * hit.t;
      if (hit.axis === 'x') {
        ball.vx = -ball.vx;
      } else {
        ball.vy = -ball.vy;
      }
      killBrick(state, brick);
    }
  }

  // Paddle: swept top-face check. The old discrete window for the ball center
  // (y in [441, 453]) is only 12 px tall, and from level 7 on the ball moves
  // 13.3 px per frame at 60 fps — it used to jump straight through the paddle.
  if (ball.vy > 0 && ball.x >= paddle.x && ball.x <= paddle.x + paddle.w) {
    const prevBottom = prevY + ball.r;
    const inBand = ball.y + ball.r > paddle.y && ball.y - ball.r < paddle.y + paddle.h;
    if ((prevBottom <= paddle.y && ball.y + ball.r >= paddle.y) || inBand) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      const speed = ballSpeed(state.level);
      ball.vx = 0.6 * speed * hit;
      // Keep the level speed: |v| must stay ballSpeed(level) whatever the
      // angle, so vy is derived from vx instead of keeping its old magnitude.
      ball.vy = -Math.sqrt(Math.max(0, speed * speed - ball.vx * ball.vx));
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

