  WIDTH,
} from './neon.js';

edits.newText:
test('step: ball overlapping a brick bounces back off the face it hit', () => {
  const state = createState(1);
  state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
  // 3 px inside the left face: vx must flip, vy must stay untouched.
  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx should flip away from the left face');
  assert.equal(state.ball.vy, 30, 'vy must stay untouched on a side hit');
});

test('step: ball is pushed out of the brick it overlapped', () => {
  const state = createState(1);
  state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };
  step(state, 1 / 60);
  assert.ok(state.ball.x + BALL_R <= 100, 'right edge must come back to the left face');
});

test('step: equal penetration on both axes (corner) flips both components', () => {
  const state = createState(1);
  state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
  state.ball = { x: 96, y: 96, r: BALL_R, vx: 300, vy: 300 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'vx should flip on the corner');
  assert.ok(state.ball.vy < 0, 'vy should flip on the corner');
});

test('step: fast ball (level 6, dt max) does not tunnel through a brick', () => {
  const state = createState(6);
  const brick = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
  state.bricks = [brick];
  // One 50 ms frame moves the ball 35.5 px, more than the 34 px needed to jump
  // the brick: only a swept test between the two positions can see the hit.
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'the brick must be hit, not jumped over');
  assert.ok(state.ball.vy > 0, 'the ball must bounce back down');
});

test('step: fast ball does not tunnel through the paddle (level 7)', () => {
  const state = createState(7);
  const paddle = state.paddle;
  // One frame at 60 fps moves the ball 13.3 px, more than the 12 px capture
  // window of the paddle: it must still bounce off the top face.
  state.ball = {
    x: paddle.x + paddle.w / 2,
    y: paddle.y - BALL_R - 0.1,
    r: BALL_R,
    vx: 0,
    vy: ballSpeed(7),
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'the ball should bounce off the paddle');
});

test('step: paddle bounce keeps the level speed', () => {
  const state = createState(1);
  const paddle = state.paddle;
  // Edge hit (hit = 1): the old code wrote vx = 0.6*s without renormalizing,
  // giving |v| = s*sqrt(1.36) instead of s.
  state.ball = { x: paddle.x + paddle.w, y: paddle.y - BALL_R, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(
    Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - ballSpeed(1)) < 1e-9,
    'speed should stay ballSpeed(level)',
  );
});

