  // A fast ball (level >= 6 on a 50 ms frame moves 35.5 px, more than the
  // 34 px it takes to jump a brick) never overlaps a brick at either endpoint,
  // so only the segment crossing reveals the hit. The earliest contact wins.
  if (!bounced) {
    let first = null;
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      const hit = sweptHit(prevX, prevY, ball.x, ball.y, brick, ball.r);
      if (hit && (first === null || hit.t < first.hit.t)) {
        first = { brick, hit };
      }
